// Blocks the census found by itself, keyed by batch year the way `CENSUS_COLLEGES`
// is (26 = 2026). Generated by `scripts/census-intake.mjs --discover`; do not
// hand-edit, the next discovery run rewrites this file.
//
// A code lands here only when `YY01CCC001` answers with a record that names that
// same registration number, which is what lets the sweep run unattended: the
// portal echoes `rollNo`, `batch` and `collegeCode`, so a misrouted answer cannot
// add a college that does not exist. Discovery only ever adds, a code that stops
// answering stays in the grid as an empty block, because "the portal closed a
// college" and "the portal hiccupped" are indistinguishable from one probe, and
// shrinking a published population is not something a nightly job may decide.
//
// `CENSUS_DISCOVERED_AT` is the last day the grid gained anything. An empty map
// is a normal state: it means the declared lists in `census-blocks.ts` still
// describe every block the portal answers for.

/** The last day discovery added a block to this file. */
export const CENSUS_DISCOVERED_AT = "2026-09-29";

// prettier-ignore
export const CENSUS_DISCOVERED: Record<number, readonly number[]> = {};
